if(typeof require==='function'){var Classy=require('./classy');}var PlayerState=Classy.newClass().name('PlayerState');PlayerState.fields({data:{playerId:"",queued:false,enqueueTime:null,team:0}});PlayerState.constructor('withState',function(playerId,queued,enqueueTime,team){this.data.playerId=playerId;this.data.queued=queued;this.data.enqueueTime=enqueueTime;this.data.team=team;});PlayerState.constructor('withObject',function(obj){this.data=obj;});PlayerState.methods({getPlayerId:function(){return this.data.playerId;},getQueued:function(){return this.data.queued;},getEnqueueTime:function(){return this.data.enqueueTime;},getTeam:function(){return this.data.team;},toObj:function(){return this.data;}});if(typeof module==='object'){module.exports=PlayerState;}